<script setup lang="ts">
import { ref } from 'vue'
import { open } from '@tauri-apps/api/dialog'
import Modal from '@/components/ui/Modal.vue'
import { useZipEditStore } from '@/stores/zipEdit'
import { useAppStore } from '@/stores/app'
const store=useZipEditStore(),app=useAppStore(),discardTarget=ref(''),error=ref('')
async function openDraft(path:string){error.value='';const result=await store.restoreDraft(path);if(result.published){store.recoveryVisible=false;app.setSuccess(store.recoveryFeedback);app.openArchiveInBrowser(result.published)}else if(result.path){store.recoveryVisible=false;const session=store.sessionFor(result.path);app.openArchiveInBrowser(result.path,{password:session?.sourcePassword,zipPasswordEncoding:session?.sourceEncoding})}}
async function locate(source:string){error.value='';try{const queued=import.meta.env.VITE_DESKTOP_E2E==='1'?window.__LONG_DECOMPRESS_DESKTOP_E2E__?.takeDesktopDialogSelection():undefined,picked=queued===undefined?await open({title:'重新定位原 ZIP',multiple:false,filters:[{name:'ZIP',extensions:['zip']}]}):queued,path=typeof picked==='string'?picked:Array.isArray(picked)?picked[0]:undefined;if(!path)return;const relocated=await store.relocateSource(source,path);if(relocated)await openDraft(relocated)}catch(value){error.value=String(value)}}
async function retrySave(){await store.initialize();await store.flush()}
</script>
<template>
 <div v-if="store.draftCount||store.saveError" class="shrink-0 border-b border-primary/15 bg-primary/5 px-4 py-2 text-xs" data-testid="zip-edit-recovery-notice"><div class="flex min-w-0 flex-wrap items-center gap-2"><i class="pi pi-file-edit shrink-0 text-primary"></i><span class="min-w-0 flex-1 break-words [overflow-wrap:anywhere]">{{ store.saveError||`有 ${store.draftCount} 份 ZIP 编辑尚未另存` }}</span><button v-if="store.saveError" class="recovery-button text-primary" @click="retrySave">重试保存草稿</button><button class="recovery-button text-primary" data-testid="zip-edit-recovery-open" @click="store.recoveryVisible=true">编辑草稿{{ store.draftCount?`（${store.draftCount}）`:'' }}</button></div></div>
 <Modal v-model:visible="store.recoveryVisible" title="ZIP 编辑草稿" icon="pi pi-history" size="lg" cancel-text="关闭编辑草稿">
  <p class="mb-3 text-xs leading-relaxed text-muted">修改和配置已保留，密码需要重新填写。打开后核对变化或缺失的来源，再确认另存；恢复不会自动执行。</p>
  <ul class="max-h-96 space-y-3 overflow-y-auto custom-scrollbar"><li v-for="draft in store.allDrafts" :key="draft.sourcePath" class="min-w-0 space-y-3 rounded-xl border border-subtle bg-input/20 p-3" :data-draft-source="draft.sourcePath"><strong class="block break-words text-sm [overflow-wrap:anywhere]">{{ draft.sourcePath }}</strong><p class="text-xs text-muted">{{ draft.changes }} 项修改 · {{ draft.recovered?'上次编辑':draft.savedAt }}{{ store.sessionFor(draft.sourcePath)?.busy?' · 正在保存':'' }}</p><div class="flex flex-wrap gap-2"><button class="recovery-button bg-primary text-white" :disabled="store.recoveryBusy||store.sessionFor(draft.sourcePath)?.busy" data-testid="zip-edit-recover-one" @click="openDraft(draft.sourcePath)">{{ draft.recovered?'恢复并打开':'继续编辑' }}</button><button class="recovery-button text-primary" :disabled="store.recoveryBusy||store.sessionFor(draft.sourcePath)?.busy" data-testid="zip-edit-recovery-locate" @click="locate(draft.sourcePath)">定位原 ZIP</button><button class="recovery-button text-muted" :disabled="store.recoveryBusy||store.sessionFor(draft.sourcePath)?.busy" data-testid="zip-edit-recovery-discard" @click="discardTarget=draft.sourcePath">放弃草稿</button></div></li></ul>
  <p v-if="!store.allDrafts.length" class="py-4 text-xs text-muted">没有未保存的 ZIP 编辑。</p><p v-if="store.recoveryFeedback" class="mt-3 break-words text-xs leading-relaxed text-primary [overflow-wrap:anywhere]" data-testid="zip-edit-recovery-feedback">{{ store.recoveryFeedback }}</p><p v-if="error" role="alert" class="mt-3 break-words text-xs text-red-500 [overflow-wrap:anywhere]">{{ error }}</p>
 </Modal>
 <Modal :visible="!!discardTarget" @update:visible="discardTarget=''" title="放弃这份编辑草稿？" description="原包和已保存结果保留" size="sm" layer="nested" cancel-text="继续保留" confirm-text="放弃草稿" @confirm="store.discardDraft(discardTarget);discardTarget=''"><p class="break-words text-xs leading-relaxed text-muted [overflow-wrap:anywhere]">{{ discardTarget }}</p></Modal>
</template>
<style scoped>.recovery-button{display:inline-flex;align-items:center;justify-content:center;border:1px solid var(--border-subtle);border-radius:.65rem;padding:.45rem .7rem;font-size:.75rem}button:disabled{opacity:.45;cursor:default}</style>
